SELECT value->>'id', value->>'name', value FROM jsonb_array_elements('[{"id": "Bodyweight_Squat", "name": "Sentadilla sin peso", "category": "Piernas", "equipment": "Sin equipo", "steps": ["De pie, separa los pies a una anchura cómoda.", "Lleva la cadera atrás y flexiona las rodillas sin perder el apoyo de los pies.", "Vuelve a subir con control. Usa un recorrido que puedas mantener sin dolor."], "images": ["assets/exercises/Bodyweight_Squat/0.jpg", "assets/exercises/Bodyweight_Squat/1.jpg"], "source": "free-exercise-db", "sourceUrl": "https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bodyweight_Squat.json", "level": "Inicial", "tip": "Mantén un ritmo que te permita controlar el movimiento. Detente si aparece dolor."}, {"id": "Pushups", "name": "Flexiones en el suelo", "category": "Tren superior", "equipment": "Sin equipo", "steps": ["Apoya manos y puntas de los pies con el cuerpo alineado.", "Flexiona los codos y acerca el pecho al suelo con control.", "Empuja para volver. Si necesitas una variante más sencilla, elige flexiones en pared."], "images": ["assets/exercises/Pushups/0.jpg", "assets/exercises/Pushups/1.jpg"], "source": "free-exercise-db", "sourceUrl": "https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Pushups.json", "level": "Intermedio", "tip": "Mantén un ritmo que te permita controlar el movimiento. Detente si aparece dolor."}, {"id": "Plank", "name": "Plancha sobre antebrazos", "category": "Zona media", "equipment": "Sin equipo", "steps": ["Apoya los antebrazos y separa los pies a una distancia cómoda.", "Mantén el cuerpo alineado, sin hundir la zona lumbar.", "Respira con normalidad. Puedes apoyar las rodillas para reducir la dificultad."], "images": ["assets/exercises/Plank/0.jpg", "assets/exercises/Plank/1.jpg"], "source": "free-exercise-db", "sourceUrl": "https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Plank.json", "level": "Intermedio", "tip": "Mantén un ritmo que te permita controlar el movimiento. Detente si aparece dolor."}, {"id": "Butt_Lift_Bridge", "name": "Puente de glúteos", "category": "Cadera", "equipment": "Sin equipo", "steps": ["Túmbate boca arriba, con rodillas flexionadas y pies apoyados.", "Eleva la cadera de forma controlada, sin arquear la espalda.", "Baja despacio y vuelve a repetir si mantienes una postura cómoda."], "images": ["assets/exercises/Butt_Lift_Bridge/0.jpg", "assets/exercises/Butt_Lift_Bridge/1.jpg"], "source": "free-exercise-db", "sourceUrl": "https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Butt_Lift_Bridge.json", "level": "Inicial", "tip": "Mantén un ritmo que te permita controlar el movimiento. Detente si aparece dolor."}, {"id": "Dead_Bug", "name": "Extensión alterna tumbado", "category": "Zona media", "equipment": "Sin equipo", "steps": ["Túmbate boca arriba y eleva brazos y piernas flexionadas.", "Extiende un brazo y la pierna contraria hasta donde controles la espalda.", "Regresa y alterna. Reduce el recorrido si pierdes el control de la postura."], "images": ["assets/exercises/Dead_Bug/0.jpg", "assets/exercises/Dead_Bug/1.jpg"], "source": "free-exercise-db", "sourceUrl": "https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dead_Bug.json", "level": "Inicial", "tip": "Mantén un ritmo que te permita controlar el movimiento. Detente si aparece dolor."}, {"id": "Side_Leg_Raises", "name": "Elevación lateral de pierna", "category": "Cadera", "equipment": "Sin equipo", "steps": ["Túmbate de lado y apoya la cabeza de forma cómoda.", "Eleva la pierna superior sin girar el tronco.", "Baja con control y cambia de lado a mitad del tiempo."], "images": ["assets/exercises/Side_Leg_Raises/0.jpg", "assets/exercises/Side_Leg_Raises/1.jpg"], "source": "free-exercise-db", "sourceUrl": "https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side_Leg_Raises.json", "level": "Inicial", "tip": "Mantén un ritmo que te permita controlar el movimiento. Detente si aparece dolor."}, {"id": "Standing_Hip_Circles", "name": "Círculos suaves de cadera", "category": "Movilidad", "equipment": "Sin equipo", "steps": ["De pie, apoya las manos en la cintura.", "Haz círculos pequeños y lentos con la cadera.", "Cambia de dirección. Evita forzar el recorrido."], "images": ["assets/exercises/Standing_Hip_Circles/0.jpg", "assets/exercises/Standing_Hip_Circles/1.jpg"], "source": "free-exercise-db", "sourceUrl": "https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Hip_Circles.json", "level": "Inicial", "tip": "Mantén un ritmo que te permita controlar el movimiento. Detente si aparece dolor."}, {"id": "Front_Leg_Raises", "name": "Elevación frontal de pierna", "category": "Movilidad", "equipment": "Sin equipo", "steps": ["De pie, mantén el tronco erguido y busca un apoyo si lo necesitas.", "Eleva una pierna al frente hasta una altura cómoda.", "Baja con control y alterna las piernas, sin balanceos bruscos."], "images": ["assets/exercises/Front_Leg_Raises/0.jpg", "assets/exercises/Front_Leg_Raises/1.jpg"], "source": "free-exercise-db", "sourceUrl": "https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Front_Leg_Raises.json", "level": "Inicial", "tip": "Mantén un ritmo que te permita controlar el movimiento. Detente si aparece dolor."}, {"id": "wall-push", "name": "Flexiones en pared", "category": "Tren superior", "equipment": "Sin equipo", "steps": ["Apoya las manos en una pared firme, algo más abiertas que los hombros.", "Da un paso atrás y flexiona los codos para acercarte a la pared.", "Empuja despacio para volver, manteniendo el cuerpo alineado."], "images": [], "source": "elitecore-original", "level": "Inicial", "tip": "Ajusta el ritmo y el recorrido a lo que te resulte cómodo."}, {"id": "march", "name": "Marcha en el sitio", "category": "Resistencia", "equipment": "Sin equipo", "steps": ["Ponte de pie en un lugar despejado.", "Alterna los apoyos elevando las rodillas a una altura cómoda.", "Acompaña con los brazos y regula el ritmo para poder hablar."], "images": [], "source": "elitecore-original", "level": "Inicial", "tip": "Ajusta el ritmo y el recorrido a lo que te resulte cómodo."}, {"id": "side-step", "name": "Pasos laterales", "category": "Resistencia", "equipment": "Sin equipo", "steps": ["Colócate de pie con los pies separados de forma cómoda.", "Da un paso a un lado y acerca el otro pie sin cruzarlo.", "Repite hacia el lado contrario. Mantén el movimiento suave."], "images": [], "source": "elitecore-original", "level": "Inicial", "tip": "Ajusta el ritmo y el recorrido a lo que te resulte cómodo."}, {"id": "walk", "name": "Caminar a ritmo cómodo", "category": "Activación", "equipment": "Sin equipo", "steps": ["Elige un espacio seguro o camina suavemente en el sitio.", "Mantén una postura natural y un ritmo cómodo.", "Usa este tiempo para entrar en movimiento o volver a la calma."], "images": [], "source": "elitecore-original", "level": "Inicial", "tip": "Ajusta el ritmo y el recorrido a lo que te resulte cómodo."}]'::jsonb)
