SELECT value->>'id', value->>'name', value FROM jsonb_array_elements('[{"id": "oats-fruit", "name": "Avena con yogur y fruta", "slot": "Desayuno", "minutes": 10, "servings": 2, "vegetarian": true, "allergens": ["lácteos", "gluten"], "ingredients": [{"id": "oats", "name": "Avena", "quantity": 80, "unit": "g"}, {"id": "yogurt", "name": "Yogur natural", "quantity": 250, "unit": "g"}, {"id": "banana", "name": "Banana", "quantity": 2, "unit": "unidad"}, {"id": "cinnamon", "name": "Canela", "quantity": 2, "unit": "g"}], "steps": ["Mezcla la avena con el yogur. Si prefieres una textura más suave, déjala unos minutos.", "Pela y corta las bananas.", "Reparte en dos recipientes, añade la fruta y espolvorea la canela."], "color": "#e7c99d", "source": "elitecore-original", "note": "Idea de comida para organizarte. Las porciones se pueden ajustar; no es una dieta individualizada."}, {"id": "chicken-rice", "name": "Arroz con pollo y verduras", "slot": "Almuerzo", "minutes": 30, "servings": 2, "vegetarian": false, "allergens": [], "ingredients": [{"id": "rice", "name": "Arroz", "quantity": 150, "unit": "g"}, {"id": "chicken", "name": "Pechuga de pollo", "quantity": 250, "unit": "g"}, {"id": "carrot", "name": "Zanahoria", "quantity": 150, "unit": "g"}, {"id": "broccoli", "name": "Brócoli", "quantity": 200, "unit": "g"}, {"id": "olive-oil", "name": "Aceite de oliva", "quantity": 15, "unit": "ml"}], "steps": ["Cocina el arroz siguiendo el envase. Lava las verduras y córtalas.", "Cocina el pollo por completo en una sartén con el aceite, manteniéndolo separado de los alimentos listos para comer.", "Cocina las verduras al vapor o en la sartén. Sirve con el arroz y el pollo."], "color": "#d8dfb6", "source": "elitecore-original", "note": "Idea de comida para organizarte. Las porciones se pueden ajustar; no es una dieta individualizada."}, {"id": "lentil-salad", "name": "Ensalada de lentejas", "slot": "Almuerzo", "minutes": 15, "servings": 2, "vegetarian": true, "allergens": [], "ingredients": [{"id": "lentils-cooked", "name": "Lentejas cocidas", "quantity": 400, "unit": "g"}, {"id": "tomato", "name": "Tomate", "quantity": 200, "unit": "g"}, {"id": "cucumber", "name": "Pepino", "quantity": 150, "unit": "g"}, {"id": "olive-oil", "name": "Aceite de oliva", "quantity": 15, "unit": "ml"}, {"id": "lemon", "name": "Limón", "quantity": 1, "unit": "unidad"}], "steps": ["Si usas lentejas en conserva, escúrrelas y enjuágalas.", "Lava y corta el tomate y el pepino.", "Mezcla todo y aliña con el aceite y el zumo de limón."], "color": "#c7d8a7", "source": "elitecore-original", "note": "Idea de comida para organizarte. Las porciones se pueden ajustar; no es una dieta individualizada."}, {"id": "spinach-eggs", "name": "Tortilla de espinaca y patata", "slot": "Cena", "minutes": 25, "servings": 2, "vegetarian": true, "allergens": ["huevo"], "ingredients": [{"id": "egg", "name": "Huevo", "quantity": 4, "unit": "unidad"}, {"id": "spinach", "name": "Espinaca", "quantity": 150, "unit": "g"}, {"id": "potato", "name": "Patata", "quantity": 300, "unit": "g"}, {"id": "olive-oil", "name": "Aceite de oliva", "quantity": 15, "unit": "ml"}], "steps": ["Pela y corta la patata. Cuécela hasta que esté tierna.", "Lava la espinaca y cocínala brevemente en una sartén.", "Bate los huevos, mezcla con la patata y la espinaca y cocina con el aceite hasta que el huevo esté cuajado."], "color": "#b8cea6", "source": "elitecore-original", "note": "Idea de comida para organizarte. Las porciones se pueden ajustar; no es una dieta individualizada."}, {"id": "chickpea-toast", "name": "Tostadas de garbanzo y aguacate", "slot": "Desayuno", "minutes": 12, "servings": 2, "vegetarian": true, "allergens": ["gluten"], "ingredients": [{"id": "bread", "name": "Pan integral", "quantity": 160, "unit": "g"}, {"id": "chickpeas-cooked", "name": "Garbanzos cocidos", "quantity": 200, "unit": "g"}, {"id": "avocado", "name": "Aguacate", "quantity": 1, "unit": "unidad"}, {"id": "lemon", "name": "Limón", "quantity": 1, "unit": "unidad"}, {"id": "tomato", "name": "Tomate", "quantity": 100, "unit": "g"}], "steps": ["Escurre los garbanzos y aplástalos con un tenedor.", "Añade el aguacate y unas gotas de limón.", "Tuesta el pan, extiende la mezcla y añade el tomate lavado y cortado."], "color": "#bbd3a4", "source": "elitecore-original", "note": "Idea de comida para organizarte. Las porciones se pueden ajustar; no es una dieta individualizada."}, {"id": "tuna-pasta", "name": "Pasta con atún y tomate", "slot": "Cena", "minutes": 20, "servings": 2, "vegetarian": false, "allergens": ["pescado", "gluten"], "ingredients": [{"id": "pasta", "name": "Pasta", "quantity": 160, "unit": "g"}, {"id": "tuna", "name": "Atún en conserva", "quantity": 160, "unit": "g"}, {"id": "tomato", "name": "Tomate", "quantity": 250, "unit": "g"}, {"id": "olive-oil", "name": "Aceite de oliva", "quantity": 15, "unit": "ml"}], "steps": ["Cuece la pasta siguiendo las indicaciones del envase.", "Lava y corta el tomate. Cocínalo unos minutos en la sartén con el aceite.", "Añade el atún escurrido, mezcla con la pasta y sirve."], "color": "#e4bc9c", "source": "elitecore-original", "note": "Idea de comida para organizarte. Las porciones se pueden ajustar; no es una dieta individualizada."}]'::jsonb)
